class Animal:
    def speak(self):
        return '...'
class Dog(Animal):
    def speak(self):
        return 'Woof'
print(Dog().speak())|Woof

class Animal:
    def speak(self):
        return 'generic sound'
class Dog(Animal):
    def speak(self):
        return super().speak() + ' -> Woof'
print(Dog().speak())|generic sound -> Woof

class Circle:
    def __init__(self, r):
        self._r = r
    @property
    def area(self):
        return 3.14 * self._r ** 2
print(Circle(2).area)|12.56

